let _teacherState = { sentences: [], idx: 0, playing: false };

// showTeacher(text)            → splits free-text prose into board lines by sentence/length
// showTeacher(null, lines)     → uses the given array as board lines verbatim (one slide per line),
//                                so structured lessons (e.g. IGCSE topic points) match line-by-line.
function showTeacher(text, lines, forceEn) {
  if (!('speechSynthesis' in window)) { showToast(S.lang==='en'?'Voice not supported on this device':'القراءة الصوتية غير مدعومة على هذا الجهاز', 'error'); return; }
  // stop any previous playback/timers so a fresh open never inherits a stale counter
  try { speechSynthesis.cancel(); } catch(_) {}
  if (_teacherState && _teacherState._silentTimer) clearTimeout(_teacherState._silentTimer);
  let sentences;
  if (Array.isArray(lines) && lines.length) {
    // Explicit lines mode: each line is a ready-made board "slide" — show verbatim, speak as-is.
    sentences = lines.map(s => String(s).trim()).filter(Boolean);
    if (!sentences.length) return;
  } else {
    const clean = cleanForSpeech(text);
    if (!clean) return;
    // split into board lines — one sentence per line (merge only very short fragments)
    const parts = clean.split(/(?<=[.!?؟…:])\s+/).map(s => s.trim()).filter(Boolean);
    sentences = [];
    let buf = '';
    for (const p of parts) {
      const joined = buf ? buf + ' ' + p : p;
      // keep a line until it's a reasonable length, then break (so the board fills point-by-point)
      if (buf && joined.length > 95) { sentences.push(buf); buf = p; }
      else if (joined.length >= 35 || /[.!?؟…]$/.test(p)) { sentences.push(joined); buf = ''; }
      else buf = joined;
    }
    if (buf) sentences.push(buf);
  }
  _teacherState = { sentences, idx: 0, playing: false };
  // Detect the lesson's language from its content (English lessons → English board UI + voice)
  _teacherState.en = (typeof forceEn === 'boolean') ? forceEn : !/[؀-ۿ]/.test(sentences.join(' '));

  let ov = document.getElementById('teacher-overlay');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'teacher-overlay';
    document.body.appendChild(ov);
  }
  ov.innerHTML = `
    <div class="tch-card">
      <button class="tch-close" onclick="closeTeacher()">✕</button>
      <div class="tch-classroom">
        <!-- Blackboard -->
        <div class="tch-board">
          <div class="tch-board-title">📘 ${_teacherState.en?"Today's Lesson":'درس اليوم'}</div>
          <div class="tch-board-lines" id="tch-board-lines"></div>
          <div class="tch-chalk-tray"></div>
        </div>
        <!-- 3D teacher beside the board — SVG shows by default, 3D replaces it only after it successfully renders -->
        <div class="tch-teacher-wrap" id="tch-teacher-wrap">
          <canvas id="tch-3d-canvas" style="display:none"></canvas>
          <div class="tch-avatar" id="tch-avatar" style="display:none">${TEACHER_SVG}</div>
          <div id="tch-loading" style="position:absolute;inset:0;display:flex;align-items:flex-end;justify-content:center;padding-bottom:30px;color:#bfe3cf;font-size:13px">⏳ ${S.lang==='en'?'Loading…':'تحميل…'}</div>
          <div class="tch-pointer"></div>
        </div>
      </div>
      <div class="tch-name">🎓 ${_teacherState.en?'Mr. Amin explains':'الأستاذ أمين يشرح'}</div>
      <div class="tch-controls">
        <button class="tch-btn" id="tch-prev" onclick="teacherJump(-1)">⏮</button>
        <button class="tch-btn tch-play" id="tch-play" onclick="teacherToggle()">▶️ ${_teacherState.en?'Start':'ابدأ الشرح'}</button>
        <button class="tch-btn" id="tch-next" onclick="teacherJump(1)">⏭</button>
      </div>
      <div class="tch-progress" id="tch-progress"></div>
    </div>`;
  ov.style.display = 'flex';
  renderTeacherText();
  init3DTeacher();   // load the rigged 3D human avatar (falls back to SVG if it fails)
}

/* ── Image-based teacher: uses a real PNG of Mr. Amin, animated (sway + talk bob) ── */
function initTeacherImage() {
  const wrap = document.getElementById('tch-teacher-wrap');
  const svg = document.getElementById('tch-avatar');
  const canvas = document.getElementById('tch-3d-canvas');
  if (!wrap) return;
  if (canvas) canvas.style.display = 'none';
  let img = document.getElementById('tch-img');
  if (!img) {
    img = document.createElement('img');
    img.id = 'tch-img';
    img.alt = 'الأستاذ أمين';
    img.onload = () => { if (svg) svg.style.display = 'none'; img.style.display = 'block'; };
    img.onerror = () => { img.style.display = 'none'; if (svg) svg.style.display = 'block'; }; // fall back to cartoon
    wrap.insertBefore(img, wrap.firstChild);
  }
  img.src = 'assets3d/teacher.png?v=1';
}

/* ── Built-in 3D teacher (procedural) — kept but unused ── */
async function initBuiltTeacher3D() {
  const canvas = document.getElementById('tch-3d-canvas');
  const svg = document.getElementById('tch-avatar');
  if (!canvas) return;
  let shown = false;
  const fallback = setTimeout(() => { if (!shown) { if (svg) svg.style.display='block'; canvas.style.display='none'; } }, 6000);
  const showSVG = () => { clearTimeout(fallback); if (svg) svg.style.display='block'; canvas.style.display='none'; };
  try { if (!window.WebGLRenderingContext || !canvas.getContext('webgl')) throw 0; } catch(_) { showSVG(); return; }
  try {
    if (!window.THREE) await _loadScript('https://cdn.jsdelivr.net/npm/three@0.137.0/build/three.min.js');
    const THREE = window.THREE;
    if (_t3d && _t3d.canvas === canvas) return;
    if (_t3d) _dispose3D();
    const W = canvas.clientWidth || 130, H = canvas.clientHeight || 185;
    const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(W, H, false);
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(30, W / H, 0.1, 100);
    camera.position.set(0, 1.05, 6.2);
    camera.lookAt(0, 0.55, 0);
    scene.add(new THREE.HemisphereLight(0xffffff, 0x556, 2.1));
    const key = new THREE.DirectionalLight(0xffffff, 1.8); key.position.set(2, 4, 4); scene.add(key);
    const rim = new THREE.DirectionalLight(0x88aaff, 0.6); rim.position.set(-3, 2, -2); scene.add(rim);

    const SKIN = 0xf3c9a0, SUIT = 0x33373e, SHIRT = 0xf4f6fb, TIE = 0xf5a623, HAIR = 0x5a3a22, BROWN = 0x6b4423, GLASS = 0x1a1d22;
    const mat = (c, rough=0.8) => new THREE.MeshStandardMaterial({ color: c, roughness: rough, metalness: 0.05 });
    const G = new THREE.Group();
    const head = new THREE.Group(); head.position.y = 1.55;
    // head
    const face = new THREE.Mesh(new THREE.SphereGeometry(0.34, 32, 32), mat(SKIN, 0.6));
    face.scale.set(1, 1.12, 0.95); head.add(face);
    // hair
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.355, 32, 24, 0, Math.PI*2, 0, Math.PI*0.55), mat(HAIR, 0.9));
    hair.position.y = 0.07; hair.scale.set(1.02, 1.0, 1.0); head.add(hair);
    // ears
    [-0.34, 0.34].forEach(x => { const e = new THREE.Mesh(new THREE.SphereGeometry(0.07, 16, 16), mat(SKIN, 0.6)); e.position.set(x, 0, 0); head.add(e); });
    // eyes (white + pupil)
    [-0.13, 0.13].forEach(x => {
      const w = new THREE.Mesh(new THREE.SphereGeometry(0.055, 16, 16), mat(0xffffff, 0.3)); w.position.set(x, 0.03, 0.3); head.add(w);
      const p = new THREE.Mesh(new THREE.SphereGeometry(0.028, 12, 12), mat(0x2a1a10, 0.3)); p.position.set(x, 0.03, 0.345); head.add(p);
    });
    // glasses (two rings + bridge)
    [-0.13, 0.13].forEach(x => { const r = new THREE.Mesh(new THREE.TorusGeometry(0.085, 0.018, 12, 24), mat(GLASS, 0.4)); r.position.set(x, 0.03, 0.31); head.add(r); });
    const bridge = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.1, 8), mat(GLASS, 0.4)); bridge.rotation.z = Math.PI/2; bridge.position.set(0, 0.03, 0.32); head.add(bridge);
    // eyebrows
    [-0.13, 0.13].forEach(x => { const b = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.022, 0.04), mat(HAIR, 0.9)); b.position.set(x, 0.15, 0.31); head.add(b); });
    // nose
    const nose = new THREE.Mesh(new THREE.SphereGeometry(0.045, 12, 12), mat(SKIN, 0.6)); nose.position.set(0, -0.04, 0.35); head.add(nose);
    // mouth (scales on Y while talking)
    const mouth = new THREE.Mesh(new THREE.SphereGeometry(0.07, 16, 12), mat(0x8b3a2e, 0.5));
    mouth.scale.set(1, 0.35, 0.5); mouth.position.set(0, -0.17, 0.31); head.add(mouth);
    G.add(head);
    // neck
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.12, 0.18, 16), mat(SKIN, 0.6)); neck.position.y = 1.32; G.add(neck);
    // torso (suit jacket)
    const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.4, 0.95, 24), mat(SUIT)); torso.position.y = 0.78; G.add(torso);
    // shirt V + collar
    const shirt = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.2, 0.6, 16), mat(SHIRT)); shirt.position.set(0, 0.95, 0.16); shirt.scale.z = 0.5; G.add(shirt);
    // tie
    const tie = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.5, 0.05), mat(TIE)); tie.position.set(0, 0.82, 0.27); G.add(tie);
    const knot = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 0.06), mat(0xd98e0f)); knot.position.set(0, 1.08, 0.28); G.add(knot);
    // arms (crossed-ish, slightly forward)
    const armL = new THREE.Group(); armL.position.set(-0.36, 1.02, 0.05);
    const upperL = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.09, 0.55, 16), mat(SUIT)); upperL.position.y = -0.22; armL.add(upperL);
    armL.rotation.z = 0.35; armL.rotation.x = -0.25; G.add(armL);
    const armR = new THREE.Group(); armR.position.set(0.36, 1.02, 0.05);
    const upperR = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.09, 0.55, 16), mat(SUIT)); upperR.position.y = -0.22; armR.add(upperR);
    armR.rotation.z = -0.35; armR.rotation.x = -0.25; G.add(armR);
    // hands
    [[-0.52,0.7],[0.52,0.7]].forEach(([x,y]) => { const h = new THREE.Mesh(new THREE.SphereGeometry(0.085,16,16), mat(SKIN,0.6)); h.position.set(x*0.85,y,0.18); G.add(h); });
    // legs
    [-0.16, 0.16].forEach(x => { const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.1, 0.7, 16), mat(0x2b2f35)); leg.position.set(x, 0.0, 0); G.add(leg); });
    // shoes
    [-0.16, 0.16].forEach(x => { const sh = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.1, 0.32), mat(BROWN, 0.5)); sh.position.set(x, -0.38, 0.06); G.add(sh); });

    G.position.y = -0.55; G.rotation.y = 0.15; scene.add(G);
    _t3d = { THREE, renderer, scene, camera, canvas, group: G, head, mouth, armR, raf: 0, clock: new THREE.Clock(), built: true };
    shown = true; clearTimeout(fallback);
    if (svg) svg.style.display = 'none'; canvas.style.display = 'block';
    _animateBuilt();
  } catch (e) { showSVG(); }
}
function _animateBuilt() {
  if (!_t3d || !_t3d.built) return;
  const { renderer, scene, camera, head, mouth, group, armR } = _t3d;
  const t = performance.now();
  const speaking = _teacherState.playing && (window.speechSynthesis ? speechSynthesis.speaking : false) || (_teacherState.playing && _teacherState._silentTimer);
  // idle sway
  group.rotation.y = 0.15 + Math.sin(t/1400) * 0.06;
  group.position.y = -0.55 + Math.sin(t/900) * 0.012;
  // talking: mouth opens, head nods, right arm gestures
  if (mouth) { const o = speaking ? (0.35 + 0.6*Math.abs(Math.sin(t/110))) : 0.35; mouth.scale.y += (o - mouth.scale.y)*0.4; }
  if (head) head.rotation.x = speaking ? Math.sin(t/350)*0.05 : 0;
  if (armR) armR.rotation.x = speaking ? -0.25 + Math.sin(t/300)*0.18 : -0.25;
  renderer.render(scene, camera);
  _t3d.raf = requestAnimationFrame(_animateBuilt);
}

/* ── 3D teacher (Three.js) — loaded lazily, falls back to SVG ── */
let _t3d = null; // { renderer, scene, camera, mixer, actions, current, head, raf }
function _loadScript(src) {
  return new Promise((res, rej) => {
    const s = document.createElement('script');
    s.src = src; s.onload = res; s.onerror = rej;
    document.head.appendChild(s);
  });
}
async function init3DTeacher() {
  const canvas = document.getElementById('tch-3d-canvas');
  const svg = document.getElementById('tch-avatar');
  if (!canvas) return;
  // Safety: if the 3D model isn't rendering within 7s, keep the 2D SVG visible
  let _shown3D = false;
  const hideLoading = () => { const ld = document.getElementById('tch-loading'); if (ld) ld.remove(); };
  const fallbackTimer = setTimeout(() => {
    if (!_shown3D) { hideLoading(); if (svg) svg.style.display = 'block'; canvas.style.display = 'none'; }
  }, 7000);
  const showSVG = () => { clearTimeout(fallbackTimer); hideLoading(); if (svg) svg.style.display = 'block'; canvas.style.display = 'none'; };
  // WebGL support check
  try {
    if (!window.WebGLRenderingContext || !canvas.getContext('webgl')) throw new Error('no webgl');
  } catch (_) { showSVG(); return; }
  try {
    if (!window.THREE) {
      await _loadScript('https://cdn.jsdelivr.net/npm/three@0.137.0/build/three.min.js');
    }
    if (!window.THREE.GLTFLoader) {
      await _loadScript('https://cdn.jsdelivr.net/npm/three@0.137.0/examples/js/loaders/GLTFLoader.js');
    }
    if (!window.THREE.DRACOLoader) {
      await _loadScript('https://cdn.jsdelivr.net/npm/three@0.137.0/examples/js/loaders/DRACOLoader.js');
    }
    const THREE = window.THREE;
    // reuse if already built
    if (_t3d && _t3d.canvas === canvas) return;
    if (_t3d) _dispose3D();
    const W = canvas.clientWidth || 110, H = canvas.clientHeight || 150;
    const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(W, H, false);
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(26, W / H, 0.1, 100);
    camera.position.set(0, 1.30, 2.15);   // waist-up presenter framing → face reads clearly
    camera.lookAt(0, 1.30, 0);
    scene.add(new THREE.HemisphereLight(0xffffff, 0x445, 2.8));
    const dir = new THREE.DirectionalLight(0xffffff, 2.2); dir.position.set(2, 4, 3); scene.add(dir);
    const face = new THREE.DirectionalLight(0xffffff, 1.6); face.position.set(0, 1.7, 4); scene.add(face); // front light on the face
    _t3d = { THREE, renderer, scene, camera, canvas, mixer: null, actions: {}, current: null, head: null, talkMorph: null, raf: 0, clock: new THREE.Clock() };
    const loader = new THREE.GLTFLoader();
    const draco = new THREE.DRACOLoader();
    draco.setDecoderPath('https://cdn.jsdelivr.net/npm/three@0.137.0/examples/js/libs/draco/');
    loader.setDRACOLoader(draco);
    loader.load('assets3d/teacher-human.glb?v=2', (gltf) => {
      const model = gltf.scene;
      model.scale.set(1, 1, 1);
      model.position.set(0, 0, 0);
      model.rotation.y = 0.06;
      scene.add(model);
      _t3d.model = model;

      // find the face mesh (most morphs), head, and bones
      let morphMesh = null, best = 0; const bones = {};
      model.traverse(o => {
        if (o.isBone) bones[o.name] = o;
        if (o.isMesh && o.morphTargetInfluences && o.morphTargetInfluences.length > best) { best = o.morphTargetInfluences.length; morphMesh = o; }
        if (/head/i.test(o.name)) _t3d.head = o;
      });
      _t3d.morphMesh = morphMesh;

      // Lower the arms out of the default T-pose (Mixamo upper-arm +localX lowers them)
      const bn = Object.keys(bones), findB = re => bones[bn.find(n => re.test(n))];
      const LA = findB(/LeftArm$/), RA = findB(/RightArm$/), LF = findB(/LeftForeArm$/), RF = findB(/RightForeArm$/);
      if (LA) LA.rotation.x += 1.2; if (RA) RA.rotation.x += 1.2;
      if (LF) LF.rotation.x += 0.18; if (RF) RF.rotation.x += 0.18;
      _t3d.armR = RA; _t3d.armRrest = RA ? RA.rotation.x : 0;
      model.updateMatrixWorld(true);

      // Detect mouth-open + blink morphs (VRoid numeric morphs are unnamed)
      _t3d.mouthIdx = []; _t3d.blinkIdx = [];
      const mg = morphMesh && morphMesh.geometry, mAttr = mg && mg.morphAttributes && mg.morphAttributes.position;
      if (mAttr) {
        const pos = mg.attributes.position, N = pos.count;
        let minY = 1e9, maxY = -1e9; for (let i = 0; i < N; i++){ const y = pos.getY(i); if (y<minY) minY=y; if (y>maxY) maxY=y; }
        const low = minY + (maxY - minY) * 0.35;
        const st = mAttr.map((mp, t) => { let mv=0, sdy=0, lw=0; for (let i=0;i<N;i++){ const d=Math.abs(mp.getX(i))+Math.abs(mp.getY(i))+Math.abs(mp.getZ(i)); if(d>1e-5){ mv++; sdy+=mp.getY(i); if(pos.getY(i)<low) lw++; } } return {t,mv,ady:mv?sdy/mv:0,lw}; });
        _t3d.mouthIdx = st.filter(s => s.lw>20 && s.ady<-0.002).sort((a,b)=>a.ady-b.ady).slice(0,4).map(s=>s.t);
        _t3d.blinkIdx = st.filter(s => s.lw===0 && s.mv>300 && s.ady<0).sort((a,b)=>b.mv-a.mv).slice(0,1).map(s=>s.t);
      }

      const mixer = new THREE.AnimationMixer(model);
      _t3d.mixer = mixer;
      (gltf.animations || []).forEach(clip => { _t3d.actions[clip.name] = mixer.clipAction(clip); });
      const idle = _t3d.actions['idle_eyes'] || _t3d.actions['idle_eyes_2'] || _t3d.actions['Idle'] || Object.values(_t3d.actions)[0];
      if (idle) { idle.play(); _t3d.current = idle; }
      _t3d.blinkTimer = 0; _t3d.nextBlink = 2;
      _shown3D = true;
      clearTimeout(fallbackTimer);
      hideLoading();
      if (svg) svg.style.display = 'none';
      canvas.style.display = 'block';
      _animate3D();
    }, undefined, () => {
      // model failed — fall back to SVG
      showSVG(); _dispose3D();
    });
  } catch (e) {
    showSVG();
  }
}
function _animate3D() {
  if (!_t3d) return;
  const { renderer, scene, camera, mixer, clock } = _t3d;
  const dt = clock.getDelta();
  const t = performance.now() / 1000;
  if (mixer) mixer.update(dt);

  // Is Mr. Amin speaking? (covers Edge audio OR device SpeechSynthesis)
  const speaking = !!(_teacherState.playing && (
    (window.speechSynthesis && speechSynthesis.speaking) ||
    (_teacherState._audio && !_teacherState._audio.paused && !_teacherState._audio.ended)
  ));

  // Procedural idle (model has no idle clips): gentle sway + breathing
  if (_t3d.model) {
    _t3d.model.rotation.y = 0.06 + Math.sin(t * 0.6) * 0.06;
    _t3d.model.position.y = Math.sin(t * 1.1) * 0.012;
  }

  // Blink
  if (_t3d.morphMesh && _t3d.blinkIdx && _t3d.blinkIdx.length) {
    _t3d.blinkTimer += dt; let blink = 0;
    if (_t3d.blinkTimer > _t3d.nextBlink) {
      const p = _t3d.blinkTimer - _t3d.nextBlink;
      blink = p < 0.06 ? p / 0.06 : p < 0.12 ? 1 - (p - 0.06) / 0.06 : 0;
      if (p >= 0.12) { _t3d.blinkTimer = 0; _t3d.nextBlink = 2 + Math.random() * 3; }
    }
    _t3d.blinkIdx.forEach(i => { _t3d.morphMesh.morphTargetInfluences[i] = blink; });
  }

  // Mouth: oscillate while speaking
  if (_t3d.morphMesh && _t3d.mouthIdx && _t3d.mouthIdx.length) {
    const open = speaking ? (0.06 + (0.5 + 0.5 * Math.sin(t * 12)) * 0.34) : 0;  // subtle, natural
    const inf = _t3d.morphMesh.morphTargetInfluences;
    _t3d.mouthIdx.forEach(i => { inf[i] += (open - inf[i]) * 0.5; });
  }
  if (_t3d.talkMorph) {
    const target = speaking ? (0.35 + 0.35 * Math.sin(performance.now() / 90)) : 0;
    const inf = _t3d.talkMorph.mesh.morphTargetInfluences;
    inf[_t3d.talkMorph.index] += (target - inf[_t3d.talkMorph.index]) * 0.4;
  }

  // Head nod + subtle arm gesture while speaking
  if (_t3d.head) _t3d.head.rotation.x = speaking ? Math.sin(t * 2.4) * 0.05 : 0;
  if (_t3d.armR) {
    const targetX = speaking ? (_t3d.armRrest - 0.18 + Math.sin(t * 3) * 0.14) : _t3d.armRrest;
    _t3d.armR.rotation.x += (targetX - _t3d.armR.rotation.x) * 0.12;
  }

  renderer.render(scene, camera);
  _t3d.raf = requestAnimationFrame(_animate3D);
}
function _teacher3DGesture(on) {
  if (!_t3d || !_t3d.mixer) return;
  const A = _t3d.actions;
  const talk = A['Yes'] || A['Wave'] || A['ThumbsUp'] || null;
  const idle = A['Idle'] || Object.values(A)[0];
  const next = on ? (talk || idle) : idle;
  if (!next || next === _t3d.current) return;
  if (_t3d.current) _t3d.current.fadeOut(0.3);
  next.reset().fadeIn(0.3).play();
  if (on && talk) { next.setLoop(_t3d.THREE.LoopRepeat); }
  _t3d.current = next;
}
function _dispose3D() {
  if (!_t3d) return;
  cancelAnimationFrame(_t3d.raf);
  try { _t3d.renderer.dispose(); } catch (_) {}
  _t3d = null;
}

function renderTeacherText() {
  const t = _teacherState;
  const board = document.getElementById('tch-board-lines');
  const pg = document.getElementById('tch-progress');
  if (board) {
    // Show all sentences up to current as written board lines; current one highlighted + "being written"
    board.innerHTML = t.sentences.slice(0, t.idx + 1).map((s, i) =>
      `<div class="tch-line ${i === t.idx ? 'writing' : ''}">• ${s}</div>`
    ).join('');
    board.scrollTop = board.scrollHeight;
  }
  if (pg) pg.textContent = `${Math.min(t.idx + 1, t.sentences.length)} / ${t.sentences.length}`;
}

function teacherSpeakCurrent() {
  const t = _teacherState;
  if (t.idx >= t.sentences.length) { teacherStop(); return; }
  renderTeacherText();
  ensureVoices(() => _teacherSpeakNow());
}
function _teacherSpeakNow() {
  const t = _teacherState;
  if (!t.playing || t.idx >= t.sentences.length) return;
  speechSynthesis.cancel();
  // Board shows the raw line (keeps "x = y", emoji); narration speaks a speech-cleaned version.
  const sentence = cleanForSpeech(t.sentences[t.idx]) || t.sentences[t.idx];
  const u = new SpeechSynthesisUtterance(sentence);
  const isArabic = /[؀-ۿ]/.test(sentence);
  const v = pickVoice(isArabic);
  const av = document.getElementById('tch-avatar');
  const advance = () => {
    if (!_teacherState.playing) return;
    _teacherState.idx++;
    if (_teacherState.idx < _teacherState.sentences.length) teacherSpeakCurrent();
    else teacherStop(true);
  };
  // Mr. Amin is a male teacher — use natural MALE neural voices for BOTH languages.
  // Priority for each sentence:
  //   1) Edge neural from the user's browser (ar-EG-ShakirNeural / en-US-GuyNeural) — natural, free
  //   2) Server /api/tts (Google) — consistent fallback
  //   3) Device SpeechSynthesis voice — last resort (good for English)
  //   4) Silent timed board-advance — only if nothing can speak
  if (av) av.classList.add('talking');
  _teacher3DGesture(true);
  const playUrl = (url, onErr, revoke) => {
    const audio = new Audio(url);
    _teacherState._audio = audio;
    audio.onended = () => { if (revoke) URL.revokeObjectURL(url); advance(); };
    audio.onerror = onErr;
    audio.play().catch(onErr);
  };
  const silentFallback = () => {
    if (!_teacherState._warnedNoVoice) {
      _teacherState._warnedNoVoice = true;
      showToast(S.lang==='en'?'Showing the lesson on the board (audio unavailable).':'يُعرض الدرس على السبورة (الصوت غير متاح حالياً).', 'info');
    }
    const ms = Math.max(2200, sentence.length * 75);
    _teacherState._silentTimer = setTimeout(advance, ms);
  };
  // Device SpeechSynthesis as last resort — only useful if a matching voice exists.
  const deviceFallback = () => {
    if (!v) return silentFallback();
    u.voice = v;
    u.lang = v.lang || (isArabic ? 'ar-EG' : 'en-US');
    u.rate = 0.92;
    u.onend = advance;
    u.onerror = advance;   // never hard-stop the lesson on one bad sentence
    try { speechSynthesis.speak(u); } catch (_) { silentFallback(); }
  };
  const lang = isArabic ? 'ar' : 'en';
  const edgeVoice = isArabic ? 'ar-EG-ShakirNeural' : 'en-US-GuyNeural';
  const serverFallback = () => playUrl(`${API}/tts?lang=${lang}&text=${encodeURIComponent(sentence)}`, deviceFallback, false);
  // Try the natural Edge neural voice first (skips instantly if already known blocked).
  _edgeTTS(sentence, edgeVoice)
    .then(blob => { if (_teacherState.playing) playUrl(URL.createObjectURL(blob), serverFallback, true); })
    .catch(serverFallback);
}

function _stopTeacherAudio() {
  const a = _teacherState._audio;
  if (a) { try { a.pause(); a.onended = a.onerror = null; a.src = ''; } catch(_) {} _teacherState._audio = null; }
}

function teacherToggle() {
  const t = _teacherState;
  const btn = document.getElementById('tch-play');
  if (t.playing) {
    t.playing = false;
    speechSynthesis.cancel();
    _stopTeacherAudio();
    clearTimeout(t._silentTimer);
    document.getElementById('tch-avatar')?.classList.remove('talking');
    _teacher3DGesture(false);
    if (btn) btn.innerHTML = '▶️ ' + (_teacherState.en?'Continue':'أكمل');
  } else {
    t.playing = true;
    if (btn) btn.innerHTML = '⏸️ ' + (_teacherState.en?'Pause':'إيقاف مؤقت');
    teacherSpeakCurrent();
  }
}

function teacherJump(dir) {
  const t = _teacherState;
  t.idx = Math.max(0, Math.min(t.sentences.length - 1, t.idx + dir));
  if (t.playing) teacherSpeakCurrent(); else renderTeacherText();
}

function teacherStop(finished) {
  _teacherState.playing = false;
  speechSynthesis.cancel();
  _stopTeacherAudio();
  clearTimeout(_teacherState._silentTimer);
  document.getElementById('tch-avatar')?.classList.remove('talking');
  _teacher3DGesture(false);
  const btn = document.getElementById('tch-play');
  if (btn) btn.innerHTML = (finished ? '🔁 ' : '▶️ ') + (finished ? (S.lang==='en'?'Replay':'أعد الشرح') : (S.lang==='en'?'Continue':'أكمل'));
  if (finished) _teacherState.idx = 0;
}

function closeTeacher() {
  teacherStop();
  _dispose3D();
  const ov = document.getElementById('teacher-overlay');
  if (ov) ov.style.display = 'none';
}

/* ── Text-to-Speech: read AI explanations aloud ── */
let _speakingBtn = null;
function speakText(text, btn) {
  if (!('speechSynthesis' in window)) { showToast(S.lang==='en'?'Voice not supported on this device':'القراءة الصوتية غير مدعومة على هذا الجهاز', 'error'); return; }
  // Toggle: if already speaking, stop
  if (speechSynthesis.speaking) {
    speechSynthesis.cancel();
    if (_speakingBtn) _speakingBtn.textContent = '🔊';
    if (_speakingBtn === btn) { _speakingBtn = null; return; }
  }
  // Strip markdown/HTML/emojis so it reads clean text
  const clean = String(text)
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[#*_`>|-]+/g, ' ')
    .replace(/\$\$?[^$]*\$\$?/g, ' ')
    .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, ' ')
    .replace(/\s+/g, ' ').trim();
  if (!clean) return;
  const isArabic = /[؀-ۿ]/.test(clean);
  ensureVoices(() => {
    const v = pickVoice(isArabic);
    if (isArabic && !v) {
      showToast(S.lang==='en'?'No Arabic voice installed on this device.':'لا يوجد صوت عربي مثبّت على الجهاز. أضِفه من إعدادات الجهاز.', 'error');
      if (btn) btn.textContent = '🔊'; _speakingBtn = null; return;
    }
    const u = new SpeechSynthesisUtterance(clean);
    if (v) u.voice = v;
    u.lang = v ? v.lang : (isArabic ? 'ar-SA' : 'en-US');
    u.rate = 0.92;
    u.onend = u.onerror = () => { if (btn) btn.textContent = '🔊'; _speakingBtn = null; };
    if (btn) { btn.textContent = '⏸️'; _speakingBtn = btn; }
    speechSynthesis.speak(u);
  });
}
// Some browsers load voices asynchronously
if ('speechSynthesis' in window) speechSynthesis.getVoices();

/* ── render ── */
function render() {
  // Stop any ongoing speech when the screen re-renders away
  try { if (window.speechSynthesis && speechSynthesis.speaking && !document.querySelector('.speak-btn')) speechSynthesis.cancel(); } catch(_) {}
  const el = ge('app');
  if      (S.screen === 'loading')       { el.innerHTML = tplLoading(); }
  else if (S.screen === 'login')         { el.innerHTML = tplLogin(); }
  else if (S.screen === 'signin')        { el.innerHTML = tplSignin(); }
  else if (S.screen === 'parent')        { el.innerHTML = tplParent(); }
  else if (S.screen === 'teacher')       { el.innerHTML = tplTeacher(); if (S.token) setTimeout(loadTeacherClasses, 50); }
  else if (S.screen === 'register')      { el.innerHTML = tplRegister(); }
  else if (S.screen === 'forgot')        { el.innerHTML = tplForgotPassword(); }
  else if (S.screen === 'reset-password'){ el.innerHTML = tplResetPassword(S.resetToken || ''); }
  else                                   { el.innerHTML = tplShell(screenContent()); }
  // Update study streak when on IGCSE screen
  if (S.screen === 'igcse') {
    const today = new Date().toISOString().slice(0,10);
    const streak = S.igcseStreak || {count:0, lastDate:''};
    if (streak.lastDate !== today) {
      const yesterday = new Date(Date.now()-86400000).toISOString().slice(0,10);
      streak.count = streak.lastDate === yesterday ? streak.count + 1 : 1;
      streak.lastDate = today;
      S.igcseStreak = streak;
    }
  }
  saveLocal();
  bind();
  // Render math in chat after DOM is ready
  if (S.screen === 'chat') {
    requestAnimationFrame(() => renderMath(ge('chat-msgs')));
  }
}
function screenContent() {
  const map = {
    home: tplHome, chat: tplChat, flashcards: tplFlashcards, quiz: tplQuiz,
    stats: tplStats, profile: tplProfile, notes: tplNotes,
    bookmarks: tplBookmarks, wrong: tplWrong, pomodoro: tplPomodoro,
    schedule: tplSchedule, history: tplHistory, leaderboard: tplLeaderboard,
    summary: tplSummary, mindmap: tplMindMap, textbook: tplTextbook,
    upgrade: tplUpgrade, lessons: tplLessons, admin: tplAdmin, onboarding: tplOnboarding,
    igcse: tplIGCSE, papers: tplPapers,
  };
  return (map[S.screen] || tplChat)();
}

