function _secGrade(n){
  return [
    mkSubj('الرياضيات','🔢',S_MATH,..._SEC_MATH[n]),
    mkSubj('الفيزياء','⚡',S_PHY,..._SEC_PHY[n]),
    mkSubj('الكيمياء','🧪',S_CHEM,..._SEC_CHEM[n]),
    mkSubj('الأحياء','🦠',S_BIO,..._SEC_BIO[n]),
    mkSubj('اللغة العربية','📜',S_AR,..._SEC_AR[n]),
    mkSubj('اللغة الإنجليزية','🗣️',S_EN,..._SEC_EN[n]),
    mkSubj('التاريخ','🏛️',S_HIST,'التاريخ القديم والوسيط','التاريخ الإسلامي','التاريخ الحديث والمعاصر','تاريخ الوطن'),
    mkSubj('الجغرافيا','🗺️',S_GEO,'الجغرافيا الطبيعية','الجغرافيا البشرية','الجغرافيا الاقتصادية','جغرافية الوطن'),
    mkSubj('التربية الإسلامية','☪️',S_ISL,'القرآن والتفسير','الفقه','العقيدة','الحديث والسيرة'),
    mkSubj('الفلسفة والمنطق','💭',S_PHIL,'مدخل الفلسفة','المنطق','نظرية المعرفة','الأخلاق'),
    mkSubj('الحاسب الآلي','💻',S_COMP,'البرمجة','قواعد البيانات','الشبكات','الأمن الرقمي'),
  ];
}
function _arabSecGrades(){
  const g={};const L=['','الصف الأول الثانوي','الصف الثاني الثانوي','الصف الثالث الثانوي'];
  for(let n=1;n<=3;n++)g['sec'+n]={label:L[n],subjects:_secGrade(n)};
  return g;
}
// Returns all 9 separated Arab grades (prim1-6 + prep1-3) for a country
function _arabGrades(countryHistory, extraIslam) {
  const g = {};
  const primLabels = ['','الصف الأول الابتدائي','الصف الثاني الابتدائي','الصف الثالث الابتدائي','الصف الرابع الابتدائي','الصف الخامس الابتدائي','الصف السادس الابتدائي'];
  for (let n = 1; n <= 6; n++) g['prim'+n] = { label: primLabels[n], subjects: _primGrade(n, countryHistory) };
  const prepLabels = ['','الصف الأول الإعدادي','الصف الثاني الإعدادي','الصف الثالث الإعدادي'];
  for (let n = 1; n <= 3; n++) g['prep'+n] = { label: prepLabels[n], subjects: _prepGrade(n, extraIslam) };
  return g;
}


