/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
   SHELL + NAV
   â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */
function tplShell(content) {
  const nav = [
    { s:'chat',        icon:'💬', label: t('المحادثة','chat') },
    { s:'lessons',     icon:'📖', label: t('الدروس','lessons') },
    { s:'flashcards',  icon:'🗂', label: t('البطاقات','flashcards') },
    { s:'quiz',        icon:'📝', label: t('الاختبار','quiz') },
    { s:'summary',     icon:'📋', label: t('الملخص','summary') },
    { s:'mindmap',     icon:'🧠', label: t('خريطة ذهنية','mindmap') },
    { s:'textbook',    icon:'📚', label: t('الكتب','textbook') },
    { s:'igcse',       icon:'🎓', label:'IGCSE' },
    { s:'stats',       icon:'📊', label: t('الإحصائيات','stats') },
    { s:'notes',       icon:'🗒', label: t('الملاحظات','notes') },
    { s:'bookmarks',   icon:'🔖', label: t('المحفوظات','bookmarks') },
    { s:'wrong',       icon:'❌',  label: t('الأخطاء','wrong') },
    { s:'pomodoro',    icon:'⏱',  label: t('بومودورو','pomodoro') },
    { s:'schedule',    icon:'📅', label: t('الجدول','schedule') },
    { s:'history',     icon:'🕒', label: t('السجل','history') },
    { s:'leaderboard', icon:'🏆', label: t('المتصدرون','leaderboard') },
    { s:'teacher',     icon:'👩‍🏫', label: S.lang==='en'?'Teacher':'المعلّم' },
    { s:'profile',     icon:'👤', label: t('الملف','profile') },
    { s:'upgrade',     icon:'⭐',  label:'Pro' },
    { s:'admin',       icon:'🛡', label:'Admin' },
  ].filter(n => !(IS_APP && n.s === 'upgrade'))  // hide purchase entry in ALL app builds (iOS + Android are free in-app; no IAP)
  const navItems = nav.map(n => `
    <button class="nav-item${S.screen===n.s?' active':''}" onclick="navTo('${n.s}')" style="width:100%;text-align:right;background:none;border:none;cursor:pointer;font-family:Cairo,sans-serif">
      <span class="nav-icon">${n.icon}</span>
      <span class="nav-label">${n.label}</span>
    </button>`).join('');
  const botNavScreens = ['chat','lessons','igcse','textbook','stats'];
  const botNav = [
    ...nav.filter(n => botNavScreens.includes(n.s)),
    { s:'__more__', icon:'⋯', label: S.lang==='en'?'More':'المزيد' }
  ].map(n => `
    <button class="bot-nav-item${S.screen===n.s?' active':''}" onclick="navTo('${n.s}')" style="background:none;border:none;cursor:pointer;font-family:Cairo,sans-serif;flex:1">
      <span>${n.icon}</span><span style="font-size:10px;display:block">${n.label}</span>
    </button>`).join('') +
  `<button onclick="doLogout()" style="background:none;border:none;cursor:pointer;font-family:Cairo,sans-serif;flex:1;color:#EF4444">
    <span>🚪</span><span style="font-size:10px;display:block">${S.lang==='en'?'Logout':'خروج'}</span>
  </button>`;
  const curData = CURRICULA[S.curriculum] || CURRICULA.egypt;
  const gradeData = (curData.grades && (curData.grades[S.grade] || curData.grades.high || Object.values(curData.grades)[0])) || { label: S.grade || 'ثانوي', subjects: [] };
  return `
<div class="shell">
  <aside class="sidebar">
    <div style="display:flex;align-items:center;justify-content:space-between;padding:0 8px;margin-bottom:2px">
      <div class="sidebar-logo" style="margin-bottom:0">🎓 أستاذ AI</div>
      <button onclick="doLogout()" style="background:#EF444420;border:1px solid #EF444440;color:#EF4444;padding:5px 10px;border-radius:10px;font-family:Cairo,sans-serif;font-size:12px;font-weight:800;cursor:pointer;white-space:nowrap">🚪 ${S.lang==='en'?'Logout':'خروج'}</button>
    </div>
    <div class="sidebar-cur">${curLabel(S.curriculum)} · ${gradeData.label}</div>
    <!-- Streak + stats mini bar -->
    <div style="display:flex;gap:6px;margin:6px 8px 2px;flex-wrap:wrap">
      <div style="flex:1;background:#F59E0B18;border:1px solid #F59E0B30;border-radius:10px;padding:5px 8px;text-align:center">
        <div style="font-size:13px;font-weight:900;color:#F59E0B">🔥 ${(S.igcseStreak||{count:0}).count}</div>
        <div style="font-size:9px;color:var(--text-muted)">Streak</div>
      </div>
      <div style="flex:1;background:#10B98118;border:1px solid #10B98130;border-radius:10px;padding:5px 8px;text-align:center">
        <div style="font-size:13px;font-weight:900;color:#10B981">✅ ${Object.keys(S.igcseDone||{}).length}</div>
        <div style="font-size:9px;color:var(--text-muted)">Done</div>
      </div>
    </div>
    <button onclick="S.screen='home';render()"
      style="display:flex;align-items:center;gap:8px;width:calc(100% - 16px);margin:8px 8px 4px;padding:10px 14px;
             border-radius:14px;border:none;background:linear-gradient(135deg,#3B82F6,#2563EB);
             color:#fff;cursor:pointer;font-family:Cairo,sans-serif;font-size:13px;font-weight:800;
             box-shadow:0 3px 12px #3B82F655;transition:.2s"
      onmouseover="this.style.transform='translateY(-1px)';this.style.boxShadow='0 5px 16px #3B82F677'"
      onmouseout="this.style.transform='';this.style.boxShadow='0 3px 12px #3B82F655'">
      🏠 <span>${S.lang==='en'?'Home':'الرئيسية'}</span>
    </button>
    <nav class="sidebar-nav">${navItems}</nav>
    <div style="display:flex;gap:6px;margin:10px 8px">
      <button onclick="toggleDark()" style="flex:1;background:none;border:1px solid var(--border);border-radius:14px;padding:6px 8px;color:var(--text-muted);cursor:pointer;font-size:12px;font-family:Cairo,sans-serif">
        ${S.darkMode?"🌙":"☀️"} ${S.lang==='en'?(S.darkMode?'Dark':'Light'):(S.darkMode?'داكن':'فاتح')}
      </button>
      <button onclick="toggleLang()" style="flex:1;background:none;border:1px solid var(--border);border-radius:14px;padding:6px 8px;color:var(--text-muted);cursor:pointer;font-size:12px;font-family:Cairo,sans-serif">
        ${S.lang==='ar'?'🇬🇧 EN':'🇸🇦 عر'}
      </button>
    </div>
    <!-- Logout button — always visible in sidebar -->
    <button onclick="doLogout()" style="width:calc(100% - 16px);margin:0 8px 12px;padding:10px;background:#EF444415;border:1px solid #EF444435;border-radius:14px;color:#EF4444;cursor:pointer;font-family:Cairo,sans-serif;font-size:13px;font-weight:800;display:flex;align-items:center;justify-content:center;gap:8px">
      🚪 ${S.lang==='en'?'Sign Out':'تسجيل الخروج'}
    </button>
  </aside>
  <main class="content">${content}</main>
</div>
<!-- Offline Banner -->
<div id="offline-banner" style="display:none;position:fixed;top:0;left:0;right:0;z-index:9998;
  background:#EF4444;color:#fff;text-align:center;padding:8px;font-family:Cairo,sans-serif;
  font-size:13px;font-weight:700;animation:slideDown .3s ease">
  ${S.lang==='en'?'📵 No internet connection — some features unavailable':'📵 لا يوجد اتصال بالإنترنت — بعض الميزات غير متاحة'}
</div>
<nav class="bottom-nav">${botNav}</nav>
<!-- More Drawer (mobile) -->
<div id="more-drawer-overlay" style="display:none;position:fixed;inset:0;z-index:200;background:#00000060" onclick="ge('more-drawer').style.transform='translateY(100%)';setTimeout(()=>{ge('more-drawer-overlay').style.display='none'},250)"></div>
<div id="more-drawer" style="position:fixed;bottom:0;left:0;right:0;z-index:201;background:var(--bg-card);border-radius:20px 20px 0 0;padding:20px;transform:translateY(100%);transition:transform .3s cubic-bezier(.4,0,.2,1)">
  <div style="width:40px;height:4px;background:var(--border);border-radius:2px;margin:0 auto 20px"></div>
  <div style="font-size:14px;font-weight:900;color:var(--text-muted);margin-bottom:14px">${S.lang==='en'?'Other tools':'الأدوات الأخرى'}</div>
  <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">
    ${nav.filter(n=>!['chat','lessons','flashcards','stats','admin'].includes(n.s)).map(n=>`
    <button onclick="ge('more-drawer').style.transform='translateY(100%)';setTimeout(()=>{ge('more-drawer-overlay').style.display='none'},250);S.screen='${n.s}';render()"
      style="display:flex;flex-direction:column;align-items:center;gap:6px;padding:12px 4px;background:var(--bg);border:1px solid var(--border);border-radius:12px;cursor:pointer;font-family:Cairo,sans-serif;transition:.15s"
      class="drawer-btn">
      <span style="font-size:24px">${n.icon}</span>
      <span style="font-size:11px;font-weight:700;color:var(--text)">${n.label}</span>
    </button>`).join('')}
  </div>
</div>
<!-- Floating Logout Button (mobile only) -->
<button onclick="doLogout()" id="float-logout"
  style="position:fixed;top:calc(10px + env(safe-area-inset-top,0px));left:12px;z-index:999;background:#EF444420;border:1px solid #EF444450;
         color:#EF4444;border-radius:12px;padding:6px 11px;font-family:Cairo,sans-serif;font-size:11px;
         font-weight:800;cursor:pointer;display:none;align-items:center;gap:4px">
  🚪 ${S.lang==='en'?'Logout':'خروج'}
</button>
<!-- Floating Home Button (mobile, all screens except home) -->
${S.screen!=='home' && S.screen!=='chat' ? `
<button onclick="navTo('home')" id="float-home" title="${S.lang==='en'?'Home':'الرئيسية'}"
  style="position:fixed;bottom:calc(92px + env(safe-area-inset-bottom,0px));right:14px;z-index:999;width:46px;height:46px;border-radius:50%;
         background:var(--bg-card);border:1.5px solid var(--primary);font-size:20px;cursor:pointer;
         box-shadow:0 4px 14px rgba(0,0,0,.35);display:none;align-items:center;justify-content:center">
  🏠
</button>` : ''}
<!-- Floating Feedback Button -->
<button id="b-feedback-float" title="${S.lang==='en'?'Feedback about the app?':'رأيك في التطبيق؟'}"
  style="position:fixed;bottom:calc(92px + env(safe-area-inset-bottom,0px));left:14px;z-index:999;width:42px;height:42px;border-radius:50%;
         ${S.screen==='chat' ? 'display:none!important;' : ''}
         background:var(--primary);border:none;font-size:19px;cursor:pointer;
         box-shadow:0 4px 14px #3B82F655;display:flex;align-items:center;justify-content:center;
         opacity:.85;transition:.2s" onmouseenter="this.style.opacity=1" onmouseleave="this.style.opacity=.85">
  💬
</button>
<!-- Feedback Modal -->
<div id="feedback-modal" style="display:none;position:fixed;inset:0;z-index:1000;background:#00000080;align-items:center;justify-content:center">
  <div style="background:var(--surface);border-radius:16px;padding:24px;width:90%;max-width:400px;box-shadow:0 20px 60px #000a">
    <div style="font-size:18px;font-weight:900;margin-bottom:4px">${S.lang==='en'?'💬 Feedback about the app':'💬 رأيك في التطبيق'}</div>
    <div style="font-size:13px;color:var(--text-muted);margin-bottom:10px">${S.lang==='en'?'Tell us what to improve or report a problem with the app 🙏':'أخبرنا بما نحسّنه أو بلّغ عن مشكلة في التطبيق 🙏'}</div>
    <div style="font-size:12px;color:#F59E0B;background:#F59E0B14;border:1px solid #F59E0B33;border-radius:10px;padding:8px 12px;margin-bottom:12px;line-height:1.6">${S.lang==='en'?'⚠️ This is for app feedback only — please do NOT enter personal info (name, phone, ID or account numbers).':'⚠️ هذا الصندوق لرأيك في التطبيق فقط — من فضلك لا تكتب معلومات شخصية (اسم، هاتف، أرقام هوية أو حسابات).'}</div>
    <textarea id="feedback-text" placeholder="${S.lang==='en'?'e.g. The lesson was helpful / I found a bug in…':'مثال: الشرح كان مفيداً / واجهت مشكلة في…'}" rows="4"
      style="width:100%;padding:12px;border-radius:10px;border:1.5px solid var(--border);background:var(--bg);color:var(--text);
             font-family:Cairo,sans-serif;font-size:14px;resize:none;box-sizing:border-box;margin-bottom:12px"></textarea>
    <div style="display:flex;gap:8px">
      <button class="btn btn-primary" id="b-feedback-send" style="flex:1">${S.lang==='en'?'Send 📤':'إرسال 📤'}</button>
      <button class="btn btn-secondary" id="b-feedback-close" style="flex:1">${S.lang==='en'?'Cancel':'إلغاء'}</button>
    </div>
  </div>
</div>`;
}

