// ── Sign in with Apple (iOS native bridge) ──────────────────────────────────
function requestAppleSignIn() {
  if (window.ReactNativeWebView) {
    window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'requestAppleSignIn' }));
  }
}

// ── Apple IAP (In-App Purchase via RevenueCat) ───────────────────────────────
function requestIAPPurchase(plan) {
  const msg = ge('iap-msg');
  if (msg) { msg.style.display = 'block'; msg.style.color = 'var(--text-muted)'; msg.textContent = '⏳ ' + (S.lang === 'en' ? 'Opening payment...' : 'جارٍ فتح الدفع...'); }
  if (window.ReactNativeWebView) {
    window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'requestIAPPurchase', plan }));
  }
}

function restoreIAPPurchases() {
  const msg = ge('iap-msg');
  if (msg) { msg.style.display = 'block'; msg.style.color = 'var(--text-muted)'; msg.textContent = '⏳ ' + (S.lang === 'en' ? 'Restoring...' : 'جارٍ الاستعادة...'); }
  if (window.ReactNativeWebView) {
    window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'restoreIAPPurchases' }));
  }
}

async function handleIAPSuccess(data) {
  const { customerId, plan } = data || {};
  const msg = ge('iap-msg');
  if (!customerId) { if (msg) { msg.style.color='#EF4444'; msg.textContent='❌ خطأ في البيانات'; } return; }
  if (msg) { msg.style.display='block'; msg.style.color='var(--text-muted)'; msg.textContent='⏳ ' + (S.lang==='en'?'Verifying...':'جارٍ التحقق...'); }
  try {
    const d = await req('/auth/iap-verify', 'POST', { customerId, plan });
    if (d.ok) {
      S.user.plan = 'pro';
      if (d.planExpiry) S.user.planExpiry = d.planExpiry;
      saveLocal();
      showToast(S.lang === 'en' ? '🎉 Subscription activated!' : '🎉 تم تفعيل الاشتراك!', 'success');
      S.screen = 'home';
      render();
    } else {
      if (msg) { msg.style.color='#EF4444'; msg.textContent='❌ ' + (d.error || (S.lang==='en'?'Verification failed':'فشل التحقق')); }
    }
  } catch(e) {
    if (msg) { msg.style.color='#EF4444'; msg.textContent='❌ ' + (e.message || (S.lang==='en'?'Connection error':'خطأ في الاتصال')); }
  }
}

function handleIAPError(errorMsg) {
  const msg = ge('iap-msg');
  if (msg) { msg.style.display='block'; msg.style.color='#EF4444'; msg.textContent='❌ ' + (errorMsg || (S.lang==='en'?'Purchase failed':'فشل الشراء')); }
}

async function handleAppleCredential(response) {
  if (!response || !response.identityToken) {
    showToast('فشل تسجيل الدخول بـ Apple', 'error'); return;
  }
  try {
    const body = { identityToken: response.identityToken };
    if (response.name) body.name = response.name;
    if (response.email) body.email = response.email;
    const d = await req('/auth/apple', 'POST', body);
    S.token = d.token; S.user = d.user;
    saveLocal(); S.screen = 'home'; render();
    showToast('تم تسجيل الدخول بنجاح ✅', 'success');
  } catch(e) {
    showToast(e.message || 'فشل تسجيل الدخول بـ Apple', 'error');
  }
}

// ── Delete Account ───────────────────────────────────────────────────────────
async function doDeleteAccount() {
  if (!S.token) return;
  const confirmed = confirm(S.lang === 'en'
    ? 'Are you sure you want to permanently delete your account? This cannot be undone.'
    : 'هل أنت متأكد من حذف حسابك نهائياً؟ لا يمكن التراجع عن هذا الإجراء.');
  if (!confirmed) return;
  try {
    await req('/auth/delete-account', 'DELETE');
    S.token = null; S.user = null; saveLocal();
    S.screen = 'login'; render();
    showToast(S.lang === 'en' ? 'Account deleted.' : 'تم حذف الحساب.', 'info');
  } catch(e) {
    showToast(e.message || 'حصل خطأ أثناء حذف الحساب', 'error');
  }
}

async function handleGoogleCredential(response) {
  if (!response || !response.credential) {
    showToast('فشل تسجيل الدخول بـ Google', 'error'); return;
  }
  showToast('جارٍ تسجيل الدخول...', 'info');
  try {
    const deviceId = await getDeviceFingerprint();
    const d = await req('/auth/google', 'POST', { credential: response.credential, deviceId });
    if (!d || !d.token) throw new Error('لم يتم استلام بيانات الجلسة من الخادم');
    S.token = d.token; S.user = d.user;
    if (d.user && d.user.country && d.user.country in CURRICULA) S.curriculum = d.user.country;
    saveLocal();
    S.screen = 'home'; render();
    showToast('أهلاً ' + (d.user?.name || '') + ' 👋', 'success');
  } catch(e) {
    console.error('[Google Auth Error]', e);
    showToast('❌ ' + (e.message || 'فشل تسجيل الدخول بـ Google') + ' — حاول مرة أخرى', 'error');
  }
}
// Must be on window so Google's iframe can call it
window.handleGoogleCredential = handleGoogleCredential;

async function downloadBook(url, title) {
  showToast(S.lang==='en'?'⏳ Downloading the book...':'⏳ جارٍ تحميل الكتاب...', 'info');
  // Server proxy streams the PDF (Content-Disposition: attachment, CORS-enabled).
  const proxied = `${API}/books/download?url=${encodeURIComponent(url)}&name=${encodeURIComponent(title || 'كتاب')}`;
  // Preferred path: fetch as a blob and save client-side — no tab navigation, works inside iframes,
  // shows a clear success/fail toast. Falls back to opening the proxy/source if blob fetch is blocked.
  try {
    const r = await fetch(proxied);
    if (!r.ok) throw new Error('http ' + r.status);
    const blob = await r.blob();
    const objUrl = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = objUrl;
    a.download = (title || 'book').replace(/[\/\\:*?"<>|]+/g, ' ').trim() + '.pdf';
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { try { document.body.removeChild(a); } catch(_) {} URL.revokeObjectURL(objUrl); }, 1500);
    showToast(S.lang==='en'?'✅ Book downloaded':'✅ تم تحميل الكتاب', 'success');
  } catch(e) {
    // Fallback 1: let the browser handle the proxy URL directly (attachment header still forces a save).
    try {
      const a = document.createElement('a');
      a.href = proxied; a.download = (title || 'book') + '.pdf'; a.rel = 'noopener';
      document.body.appendChild(a); a.click();
      setTimeout(() => { try { document.body.removeChild(a); } catch(_) {} }, 1000);
      showToast(S.lang==='en'?'✅ Download started':'✅ بدأ تنزيل الكتاب', 'success');
    } catch(_) {
      // Fallback 2: open the original source in a new tab.
      showToast(S.lang==='en'?'Opening in a new tab instead':'جارٍ الفتح في تبويب جديد', 'info');
      setTimeout(() => window.open(url, '_blank'), 400);
    }
  }
}

async function genAILesson() {
  if (!S.lessonSubject || !S.lessonChapter) return;
  if (S.lessonLoading) return;
  const curData   = CURRICULA[S.curriculum] || CURRICULA.egypt;
  const gradeData = (curData.grades && (curData.grades[S.grade] || Object.values(curData.grades)[0])) || { label:'' };
  const isEn = ['igcse','cambridge_alevel','edexcel','aqa','ocr','american','ib','cbse','icse','french_bac','australian','canadian','south_africa'].includes(S.curriculum);
  const chapter = S.lessonChapter, subjName = S.lessonSubject.name, label = `${curData.label||''} ${gradeData.label||''}`.trim();
  const { stage, grade, curriculum } = gradeToAPI();
  const ask = async (content, longForm=false) => {
    const d = await req('/chat', 'POST', { messages:[{role:'user',content}], subject:subjName, country:S.curriculum, curriculum, stage, grade, longForm });
    return (d.content || d.reply || d.message || d.response || '').trim();
  };
  // Single-call full lesson (used for guests, to protect the free daily quota, and as a fallback).
  const singlePrompt = isEn
    ? `Write a COMPLETE textbook-chapter lesson on "${chapter}" in ${subjName} for ${label}, so the student needs NO other source. Identify the 5-6 MAIN sub-topics; for EACH write at least 250 words (definition, everyday analogy, how & why step by step from first principles, two worked examples [basic + harder], common misconception, real-world use). Then Common Mistakes, 5 practice questions with full solutions, and a summary. At least 2500 words — mandatory. Always finish.`
    : `اكتب درساً كاملاً بعمق فصل من كتاب مدرسي عن "${chapter}" في ${subjName} — ${label}، بحيث لا يحتاج الطالب لأي مصدر آخر. حدّد ٥ إلى ٦ أجزاء فرعية رئيسية؛ ولكل جزء اكتب ٢٥٠ كلمة على الأقل (تعريف، تشبيه من الحياة، كيف ولماذا يعمل خطوة بخطوة من الأساس، مثالان محلولان [بسيط وأصعب]، الخطأ الشائع، استخدام واقعي). ثم الأخطاء الشائعة و٥ أسئلة بحلولها الكاملة وملخص. ٢٥٠٠ كلمة على الأقل — إلزامي. أنهِ الدرس كاملاً. اكتب بعربية فصحى مبسّطة وصحيحة تماماً إملائياً ونحوياً، بلا أخطاء أو كلمات مكسورة أو عامية، بأسلوب واضح ومترابط يناسب عمر الطالب.`;
  // Cache: a lesson for a given chapter/grade/curriculum/language is identical every time —
  // serve it from cache (zero AI calls) instead of regenerating and spending budget.
  const lessonCacheKey = `oa_lesson_v2_${S.curriculum}_${S.grade}_${subjName}_${chapter}_${isEn?'en':'ar'}`;
  const cacheFields = { country:S.curriculum, curriculum, stage, grade, subject:subjName, chapter, lang:isEn?'en':'ar' };
  const forceRegen = !!S._lessonForceRegen; S._lessonForceRegen = false;
  // 1) Per-device cache (instant, zero network).
  if (!forceRegen) {
    try { const cached = localStorage.getItem(lessonCacheKey); if (cached && cached.length > 200) { S.lessonContent = cached; render(); return; } } catch(_) {}
  }
  S.lessonLoading = true; S.lessonContent = ''; S.lessonProgress = isEn?'⏳ Loading…':'⏳ جارٍ التحميل…'; render();
  let generated = false;
  try {
    // 2) Global cache — another student may have already generated this exact lesson (zero AI calls).
    if (!forceRegen) {
      try {
        const g = await req('/lessons/content?' + new URLSearchParams(cacheFields).toString(), 'GET');
        if (g && g.found && g.content) { S.lessonContent = g.content; try { localStorage.setItem(lessonCacheKey, g.content); } catch(_) {} return; }
      } catch(_) {}
    }
    generated = true;   // past both caches → we will spend AI calls now
    // Guests: one call (keeps within the free daily limit). Logged-in: deep section-by-section build.
    if (!S.token) {
      S.lessonContent = await ask(singlePrompt, true) || (isEn?'❌ No response — try again':'❌ لم يصل رد — حاول مجدداً');
      return;
    }
    // 1) Get the main sub-topics.
    const listPrompt = isEn
      ? `List ONLY the 5-6 MAIN sub-topics of the lesson "${chapter}" in ${subjName} for ${label}. Return ONLY a JSON array of short titles, nothing else.`
      : `اذكر فقط الأجزاء الفرعية الرئيسية (٥ إلى ٦) لدرس "${chapter}" في ${subjName} — ${label}. أرجع فقط مصفوفة JSON من عناوين قصيرة، بدون أي شيء آخر.`;
    let subs = [];
    try { const raw = await ask(listPrompt); const m = raw.match(/\[[\s\S]*\]/); if (m) subs = JSON.parse(m[0]); } catch(_) {}
    subs = (Array.isArray(subs) ? subs : []).filter(x => typeof x === 'string' && x.trim()).slice(0, 6);
    const stillHere = () => S.screen === 'lessons' && S.lessonView === 'lesson' && S.lessonChapter === chapter;
    if (!subs.length) {
      // Couldn't get a list — fall back to a single full-lesson call.
      S.lessonContent = await ask(singlePrompt, true) || (isEn?'❌ No response — try again':'❌ لم يصل رد — حاول مجدداً');
      return;
    }
    S.lessonContent = `# ${chapter}\n`; render();
    // 2) Generate each sub-topic as its own focused, in-depth section (streams in).
    for (let i = 0; i < subs.length; i++) {
      if (!stillHere()) return;   // user navigated away — stop
      S.lessonProgress = isEn ? `✍️ Part ${i+1} of ${subs.length}: ${subs[i]}` : `✍️ الجزء ${i+1} من ${subs.length}: ${subs[i]}`;
      render();
      const secPrompt = isEn
        ? `Explain ONLY the sub-topic "${subs[i]}" of the lesson "${chapter}" (${subjName}, ${label}) in depth (about 300-400 words): a precise definition, an everyday analogy, how & why it works step by step from first principles, TWO worked examples (one basic, one harder) solved step by step, the common misconception, and a real-world use. Go straight in — no general intro.`
        : `اشرح فقط الجزء "${subs[i]}" من درس "${chapter}" (${subjName}، ${label}) بعمق (حوالي ٣٠٠-٤٠٠ كلمة): تعريف دقيق، تشبيه من الحياة، كيف ولماذا يعمل خطوة بخطوة من الأساس، مثالان محلولان (بسيط وأصعب) خطوة بخطوة، الخطأ الشائع، واستخدام واقعي. ادخل مباشرة دون مقدمة عامة. اكتب بعربية فصحى مبسّطة وصحيحة تماماً إملائياً ونحوياً، بلا أخطاء أو كلمات مكسورة أو عامية، بأسلوب واضح ومترابط يناسب عمر الطالب.`;
      let sec = ''; try { sec = await ask(secPrompt, true); } catch(_) {}   // longForm → backend forces clean formal Arabic
      if (sec) { S.lessonContent += `\n\n## ${subs[i]}\n\n${sec}`; render(); }
    }
    // 3) Closing: common mistakes + practice + summary.
    if (!stillHere()) return;
    S.lessonProgress = isEn ? '✍️ Practice & summary…' : '✍️ التمارين والملخص…'; render();
    const endPrompt = isEn
      ? `For the lesson "${chapter}" (${subjName}, ${label}) write three sections: ## Common Mistakes (each with how to avoid it), ## Practice Questions (5 questions, each with a full step-by-step solution), ## Quick Summary (key points).`
      : `لدرس "${chapter}" (${subjName}، ${label}) اكتب ثلاثة أقسام: ## الأخطاء الشائعة (مع كيفية تجنّب كل منها)، ## أسئلة تدريبية (٥ أسئلة، كل منها بحل كامل خطوة بخطوة)، ## ملخص سريع (أهم النقاط). اكتب بعربية فصحى مبسّطة وصحيحة تماماً إملائياً ونحوياً، بلا أخطاء أو كلمات مكسورة أو عامية.`;
    let endSec = ''; try { endSec = await ask(endPrompt, true); } catch(_) {}
    if (endSec) S.lessonContent += `\n\n${endSec}`;
    if (S.lessonContent.replace(/^#.*$/m,'').trim().length < 20) S.lessonContent = isEn?'❌ Could not generate — try again':'❌ تعذّر التوليد — حاول مجدداً';
  } catch(e) {
    if (!S.lessonContent) S.lessonContent = `❌ ${e.message}`;
  } finally {
    S.lessonLoading = false; S.lessonProgress = ''; render();
    // Cache the finished lesson: locally (this device) + globally (all users) so it's never regenerated.
    try {
      if (S.lessonContent && !S.lessonContent.startsWith('❌')) {
        localStorage.setItem(lessonCacheKey, S.lessonContent);
        if (generated) req('/lessons/content', 'POST', { ...cacheFields, content: S.lessonContent }).catch(()=>{});
      }
    } catch(_) {}
  }
}

// Teach a structured IGCSE topic on the board — each defined point becomes one board slide,
// matched line-by-line (no AI re-generation), with the worked example walked through after.
function teachTopicOnBoard(sk, ci, ti) {
  const subj = IGCSE_SUBJECTS[sk];
  if (!subj) return;
  const ch = (subj.chapters[S.igcseBoard] || [])[ci];
  const tp = ch && ch.topics[ti];
  if (!tp || !tp.points) return;
  const lines = [];
  lines.push(`${tp.title}.`);                       // opening slide: the topic title
  tp.points.forEach(p => lines.push(p));            // one slide per revision point
  if (tp.workedExample) {
    lines.push('Worked example:');
    tp.workedExample.split('\n').map(s => s.trim()).filter(Boolean).forEach(s => lines.push(s));
  }
  if (tp.examTips && tp.examTips.length) {
    lines.push('Exam tips:');
    tp.examTips.forEach(t => lines.push(`✔️ ${t}`));
  }
  if (tp.commonMistakes && tp.commonMistakes.length) {
    lines.push('Common mistakes to avoid:');
    tp.commonMistakes.forEach(m => lines.push(`⚠️ ${m}`));
  }
  lines.push(`That completes ${tp.title}. Review the points and try the practice questions.`);
  showTeacher(null, lines);
  setTimeout(() => { if (document.getElementById('tch-play')) teacherToggle(); }, 300); // auto-start
}

// Generate the lesson for the current chapter, then open Mr. Amin on the board
async function teachChapterOnBoard() {
  if (!S.lessonSubject || !S.lessonChapter) return;
  // English curricula → English lesson (and English board UI from the very first frame)
  const isEn = ['igcse','cambridge_alevel','edexcel','aqa','ocr','american','ib','cbse','icse','french_bac','australian','canadian','south_africa'].includes(S.curriculum);
  // Show a loading board immediately (in the lesson's language)
  showTeacher(isEn ? 'Preparing the lesson, one moment please...' : 'جارٍ تحضير الدرس، لحظة من فضلك...', null, isEn);
  const playBtn = document.getElementById('tch-play');
  if (playBtn) { playBtn.disabled = true; playBtn.innerHTML = '⏳ ' + (isEn?'Preparing...':'يحضّر الدرس...'); }
  try {
    const curData = CURRICULA[S.curriculum] || CURRICULA.egypt;
    const gradeData = (curData.grades && (curData.grades[S.grade] || Object.values(curData.grades)[0])) || { label:'' };
    const prompt = isEn
      ? `You are Mr. Amin, an expert teacher explaining to a student. Explain the lesson "${S.lessonChapter}" in ${S.lessonSubject.name} for ${curData.label} ${gradeData.label} clearly and simply, as a teacher speaking aloud. Use short clear sentences. Cover the key concepts, give 2-3 worked examples, and end with a quick summary. No headings symbols, just clear spoken explanation. IMPORTANT: Respond ONLY in English. Do not use any Arabic words at all.`
      : `اشرح درس "${S.lessonChapter}" في مادة ${S.lessonSubject.name} — ${curData.label} ${gradeData.label} بأسلوب معلّم يتحدث للطلاب على السبورة. استخدم جملاً قصيرة وواضحة. اشرح المفاهيم الأساسية، أعطِ مثالين أو ثلاثة محلولة خطوة بخطوة، واختم بملخص سريع. ابدأ فوراً دون أسئلة. لا تستخدم رموز عناوين، فقط شرح واضح مسموع.`;
    const { stage, grade, curriculum } = gradeToAPI();
    const d = await req('/chat', 'POST', {
      messages: [{ role: 'user', content: prompt }],
      subject: S.lessonSubject.name, country: S.curriculum, curriculum, stage, grade,
    });
    const content = d.content || d.reply || d.message || '';
    if (content) {
      S.lessonContent = content;
      showTeacher(content, null, isEn);            // reopen board with the real lesson (UI language = curriculum)
      setTimeout(() => { if (document.getElementById('tch-play')) teacherToggle(); }, 300); // auto-start speaking
    } else {
      const pb = document.getElementById('tch-play');
      if (pb) { pb.disabled = false; pb.innerHTML = '🔁 ' + (isEn?'Retry':'حاول مجدداً'); pb.onclick = teachChapterOnBoard; }
    }
  } catch(e) {
    const pb = document.getElementById('tch-play');
    if (pb) { pb.disabled = false; pb.innerHTML = '🔁 ' + (isEn?'Retry':'حاول مجدداً'); pb.onclick = teachChapterOnBoard; }
    showToast((isEn?'Could not prepare the lesson: ':'تعذّر تحضير الدرس: ') + (e.message||''), 'error');
  }
}

function doLogout() {
  S.token = null; S.user = null; S.messages = [];
  saveLocal(); S.screen = 'login'; render();
}

/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
   CHAT / SEND MESSAGE
   â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */
/* ── helper: map S.grade key → {stage, grade} strings for API ── */
