function L(en, ar) {
  if (S.igcseLang === 'ar') return ar || IGCSE_AR[en] || en;
  return en;
}

function toggleIGCSELang() {
  S.igcseLang = S.igcseLang === 'ar' ? 'en' : 'ar';
  document.documentElement.setAttribute('dir', S.igcseLang === 'ar' ? 'rtl' : 'ltr');
  saveLocal();
  render();
}

// Global capture-phase handler for textbook explain/summary buttons.
// Runs once at startup so it survives every render() call.
document.addEventListener('click', function(e) {
  const btn = e.target.closest('.tb-explain-btn');
  if (btn) {
    e.stopPropagation();
    openTextbookExplainByName(btn.dataset.subj, btn.dataset.curric, btn.dataset.mode);
    return;
  }
  const chBtn = e.target.closest('.tb-chapter-btn');
  if (chBtn && S.textbookExplainSubj) {
    e.stopPropagation();
    explainTextbookChapter(S.textbookExplainSubj.subj, S.textbookExplainCurric || '', chBtn.dataset.ch || '', S.textbookExplainMode || 'explain');
  }
}, true);
